const WORD_RANK_BOUNDS = [4000, 12000, 30000, 60000, 120000];
const WORD_LENGTH_BASE = { 3: 3, 4: 8, 5: 20, 6: 50, 7: 140 };
const WORD_TIER_MULTIPLIER = [1, 1.6, 2.6, 4.2, 7, 12];
const ALL_SEVEN_MULTIPLIER = 1.5;
const ALL_SEVEN_FLAT = 100;
const WORD_DECAY = 0.85;      // i-th best word counts with weight WORD_DECAY^i
const PATTERN_DECAY = 0.85;   // i-th best pattern group counts with weight PATTERN_DECAY^i
const REPEAT_LETTER_WEIGHT = 0.5; // 2nd+ copy of a letter earns half letter points
const LETTER_POINT_FACTOR = 4;    // points = round(4 * -log2(English letter frequency))
// English letter frequencies (fractions), source: standard corpus estimates
const LETTER_FREQUENCY = {
  A: 0.08167, B: 0.01492, C: 0.02782, D: 0.04253, E: 0.12702, F: 0.02228, G: 0.02015,
  H: 0.06094, I: 0.06966, J: 0.00153, K: 0.00772, L: 0.04025, M: 0.02406, N: 0.06749,
  O: 0.07507, P: 0.01929, Q: 0.00095, R: 0.05987, S: 0.06327, T: 0.09056, U: 0.02758,
  V: 0.00978, W: 0.02360, X: 0.00150, Y: 0.01974, Z: 0.00074
};
const STORAGE_KEYS = { history: 'lexdle.history.v1', stats: 'lexdle.stats.v1' };
const HISTORY_LIMIT = 200;
const HISTORY_DISPLAY = 50;

/* ---------------------------- DICTIONARY -------------------------------- */
const WORDS = new Map();          // WORD -> { rank, definition }
const BY_SIGNATURE = new Map();   // sorted letters -> [WORD, ...]
(function buildDictionary() {
  for (const [w, rank, def] of DICTIONARY_DATA) {
    const word = w.toUpperCase();
    WORDS.set(word, { rank, definition: def });
    const sig = word.split('').sort().join('');
    const list = BY_SIGNATURE.get(sig);
    if (list) list.push(word); else BY_SIGNATURE.set(sig, [word]);
  }
})();
function isWord(s) { return WORDS.has(s); }

/* ---------------------------- RANDOMNESS -------------------------------- */
// Uniform integer in [0, n) using crypto when available (rejection sampling, no modulo bias).
function randomInt(n) {
  if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
    const limit = Math.floor(0x100000000 / n) * n;
    const buf = new Uint32Array(1);
    do { crypto.getRandomValues(buf); } while (buf[0] >= limit);
    return buf[0] % n;
  }
  return Math.floor(Math.random() * n);
}

/* ---------------------------- 1. GENERATE ------------------------------- */
// Seven independent uniformly random letters; repeats allowed.
function generateLetters(rng) {
  const next = rng || randomInt;
  const letters = [];
  for (let i = 0; i < ROLL_LENGTH; i++) letters.push(ALPHABET[next(26)]);
  return letters;
}

/* --------------------------- PROFILE HELPERS ---------------------------- */
const VOWELS = new Set('AEIOU'.split(''));
const toSet = (s) => new Set(s.split(''));
const PRIMES = new Set([2, 3, 5, 7, 11, 13, 17, 19, 23]);
const FIBONACCI = new Set([1, 2, 3, 5, 8, 13, 21]);
const SQUARES = new Set([1, 4, 9, 16, 25]);
const POWERS_OF_TWO = new Set([1, 2, 4, 8, 16]);
const TRIANGULAR = new Set([1, 3, 6, 10, 15, 21]);
const RARE_FIVE = toSet('QXZJK');
const HARD_CONSONANTS = toSet('JKQVWXZ');
const TOP_TWELVE = toSet('ETAOINSHRDLU');
const TOP_NINE = toSet('ETAOINSHR');
const WHEEL_SIX = toSet('RSTLNE');
const KEY_TOP = toSet('QWERTYUIOP');
const KEY_HOME = toSet('ASDFGHJKL');
const KEY_BOTTOM = toSet('ZXCVBNM');
const STRAIGHT_LETTERS = toSet('AEFHIKLMNTVWXYZ');
const CURVED_LETTERS = toSet('CGJOSU');
const SYMMETRIC_LETTERS = toSet('AHIMOTUVWXY');
const ENCLOSED_LETTERS = toSet('ABDOPQR');

function longestChain(arr, rel) {
  let best = 1, cur = 1;
  for (let i = 1; i < arr.length; i++) {
    if (rel(arr[i - 1], arr[i])) { cur++; if (cur > best) best = cur; } else cur = 1;
  }
  return best;
}
function runLengths(mask, ch) {
  return (mask.match(new RegExp(ch + '+', 'g')) || []).map((m) => m.length);
}
function equalLetterRuns(str) {
  return (str.match(/(.)\1*/g) || []).map((m) => m.length);
}
function hasRepeatedNgram(str, n) {
  for (let i = 0; i + n <= str.length; i++) {
    const g = str.substr(i, n);
    for (let j = i + n; j + n <= str.length; j++) if (str.substr(j, n) === g) return true;
  }
  return false;
}
function hasContiguousPalindrome(str, k) {
  for (let i = 0; i + k <= str.length; i++) {
    const s = str.substr(i, k);
    if (s === s.split('').reverse().join('')) return true;
  }
  return false;
}
function hasWordInOrder(str, k) {
  for (let i = 0; i + k <= str.length; i++) if (isWord(str.substr(i, k))) return true;
  return false;
}
const reverseString = (s) => s.split('').reverse().join('');
const isPalindromeNumber = (n) => String(n) === String(n).split('').reverse().join('');

// Builds every derived fact about a roll that the pattern tests need.
function buildProfile(letters) {
  const str = letters.join('');
  const pos = letters.map((c) => c.charCodeAt(0) - 64);
  const counts = {};
  letters.forEach((c) => { counts[c] = (counts[c] || 0) + 1; });
  const partition = Object.values(counts).sort((x, y) => y - x).join('');
  const isVowel = letters.map((c) => VOWELS.has(c));
  const mask = isVowel.map((v) => (v ? 'V' : 'C')).join('');
  const diffs = [];
  for (let i = 1; i < pos.length; i++) diffs.push(pos[i] - pos[i - 1]);
  const sum = pos.reduce((s, x) => s + x, 0);
  const min = Math.min(...pos), max = Math.max(...pos);
  const sortedDistinct = [...new Set(pos)].sort((x, y) => x - y);
  const vowels = letters.filter((c) => VOWELS.has(c));
  const vowelKinds = new Set(vowels);
  const rareKinds = new Set(letters.filter((c) => RARE_FIVE.has(c)));
  return {
    letters, str, pos, counts, partition, isVowel, mask, diffs, sum, min, max, sortedDistinct,
    vowels, vowelKinds, rareKinds, vowelCount: vowels.length,
    distinct: Object.keys(counts).length,
    fixedPoints: pos.filter((p, i) => p === i + 1).length,
    ascRun: longestChain(pos, (x, y) => y === x + 1),
    descRun: longestChain(pos, (x, y) => y === x - 1),
    setRun: longestChain(sortedDistinct, (x, y) => y === x + 1),
    consonantRuns: runLengths(mask, 'C'),
    vowelRuns: runLengths(mask, 'V'),
    equalRuns: equalLetterRuns(str),
    allIn: (set) => letters.every((c) => set.has(c)),
    allPos: (fn) => pos.every(fn),
    has: (c) => counts[c] > 0,
  };
}

/* ---------------------------- 4. PATTERNS ------------------------------- */
// Each definition: id, name, description, group (overlap group), test(profile).
// tier and points are filled from PATTERN_TABLE (derived from the pattern's simulated probability).
const PATTERN_DEFS = [];
function definePattern(name, description, group, test) {
  const id = 'P' + String(PATTERN_DEFS.length + 1).padStart(3, '0');
  PATTERN_DEFS.push({ id, name, description, group, test });
}

/* Letter structure: all 15 integer partitions of 7 (exactly one always matches) */
[
  ['1111111', 'All Unique', 'Seven different letters'],
  ['211111', 'One Pair', 'One letter appears twice, the rest are unique'],
  ['22111', 'Two Pairs', 'Two letters appear twice each'],
  ['2221', 'Three Pairs', 'Three letters appear twice each'],
  ['31111', 'Triple', 'One letter appears three times'],
  ['3211', 'Full House', 'One letter three times and another twice'],
  ['322', 'Triple and Two Pairs', 'Three of one letter plus two different pairs'],
  ['331', 'Twin Triples', 'Two different letters appear three times each'],
  ['4111', 'Quad', 'One letter appears four times'],
  ['421', 'Quad and Pair', 'Four of one letter plus a pair'],
  ['43', 'Quad and Triple', 'Four of one letter and three of another'],
  ['511', 'Five of a Kind', 'One letter appears five times'],
  ['52', 'Five and Pair', 'Five of one letter and two of another'],
  ['61', 'Six of a Kind', 'One letter appears six times'],
  ['7', 'Seven of a Kind', 'All seven letters are identical'],
].forEach(([part, name, desc]) => definePattern(name, desc, 'structure', (a) => a.partition === part));

/* Adjacent repeats */
definePattern('Adjacent Pair', 'Two identical letters side by side (e.g. EE)', 'adjacent', (a) => a.equalRuns.some((r) => r >= 2));
definePattern('Two Adjacent Doubles', 'Two separate runs of doubled letters (e.g. EE and LL)', 'adjacent', (a) => a.equalRuns.filter((r) => r >= 2).length >= 2);
definePattern('Adjacent Triple', 'Three identical letters in a row', 'adjacent', (a) => a.equalRuns.some((r) => r >= 3));
definePattern('Adjacent Quad', 'Four identical letters in a row', 'adjacent', (a) => a.equalRuns.some((r) => r >= 4));
definePattern('Opening Pair', 'The first two letters are identical', 'adjacent-ends', (a) => a.letters[0] === a.letters[1]);
definePattern('Closing Pair', 'The last two letters are identical', 'adjacent-ends', (a) => a.letters[5] === a.letters[6]);

/* Alphabetical order */
definePattern('Sorted Ascending', 'Letters never go down alphabetically, left to right', 'order', (a) => a.diffs.every((d) => d >= 0));
definePattern('Strictly Ascending', 'Every letter is later in the alphabet than the previous one', 'order', (a) => a.diffs.every((d) => d > 0));
definePattern('Sorted Descending', 'Letters never go up alphabetically, left to right', 'order', (a) => a.diffs.every((d) => d <= 0));
definePattern('Strictly Descending', 'Every letter is earlier in the alphabet than the previous one', 'order', (a) => a.diffs.every((d) => d < 0));

/* Symmetry */
definePattern('Palindrome', 'The roll reads the same forwards and backwards', 'symmetry', (a) => a.str === reverseString(a.str));
definePattern('Near Palindrome', 'Exactly one mirrored pair of letters does not match', 'symmetry', (a) => [0, 1, 2].filter((i) => a.letters[i] !== a.letters[6 - i]).length === 1);
definePattern('Alphabet Mirror', 'Mirrored letters are alphabet opposites (A-Z, B-Y, C-X...)', 'symmetry', (a) => [0, 1, 2].every((i) => a.pos[i] + a.pos[6 - i] === 27));
definePattern('Equal Pair Sums', 'All three mirrored pairs have the same alphabet-position sum', 'symmetry', (a) => a.pos[0] + a.pos[6] === a.pos[1] + a.pos[5] && a.pos[1] + a.pos[5] === a.pos[2] + a.pos[4]);

/* Repeating sequences */
definePattern('Two-Letter Cycle', 'Two letters alternating through the whole roll (ABABABA)', 'repeat-seq', (a) => a.distinct === 2 && a.letters.every((c, i) => i < 2 || c === a.letters[i - 2]));
definePattern('Three-Letter Cycle', 'Three letters repeating in a cycle (ABCABCA)', 'repeat-seq', (a) => a.distinct === 3 && a.letters.every((c, i) => i < 3 || c === a.letters[i - 3]));
definePattern('Four-Letter Cycle', 'Four letters repeating in a cycle (ABCDABC)', 'repeat-seq', (a) => a.distinct === 4 && a.letters.every((c, i) => i < 4 || c === a.letters[i - 4]));
definePattern('Echo Bigram', 'The same two-letter sequence appears twice without overlapping', 'repeat-seq', (a) => hasRepeatedNgram(a.str, 2));
definePattern('Echo Trigram', 'The same three-letter sequence appears twice without overlapping', 'repeat-seq', (a) => hasRepeatedNgram(a.str, 3));

/* Consecutive runs, forward and reverse, and as an unordered set */
for (let k = 3; k <= 7; k++) {
  definePattern('Ascending Run x' + k, k + ' consecutive alphabet letters in order side by side (e.g. ' + ALPHABET.slice(3, 3 + k) + ')', 'asc-run', (a) => a.ascRun >= k);
}
for (let k = 3; k <= 7; k++) {
  definePattern('Descending Run x' + k, k + ' consecutive alphabet letters in reverse order side by side (e.g. ' + ALPHABET.slice(3, 3 + k).split('').reverse().join('') + ')', 'desc-run', (a) => a.descRun >= k);
}
for (let k = 3; k <= 7; k++) {
  definePattern('Alphabet Block x' + k, 'The roll contains ' + k + ' consecutive alphabet letters in any arrangement', 'set-run', (a) => a.setRun >= k);
}

/* Arithmetic ladders, shapes and jumps */
[2, 3, 4].forEach((d) => {
  definePattern('Ladder Step ' + d, 'Alphabet positions rise or fall by exactly ' + d + ' every step', 'arith', (a) => a.diffs.every((x) => x === d) || a.diffs.every((x) => x === -d));
});
definePattern('Zigzag', 'Letters alternate strictly up and down the alphabet', 'shape', (a) => a.diffs.every((d, i) => d !== 0 && (i === 0 || Math.sign(d) !== Math.sign(a.diffs[i - 1]))));
definePattern('Mountain', 'Letters strictly climb to a peak, then strictly descend', 'shape', (a) => {
  const k = a.diffs.findIndex((d) => d < 0);
  return k > 0 && a.diffs.slice(0, k).every((d) => d > 0) && a.diffs.slice(k).every((d) => d < 0);
});
definePattern('Valley', 'Letters strictly fall to a low point, then strictly rise', 'shape', (a) => {
  const k = a.diffs.findIndex((d) => d > 0);
  return k > 0 && a.diffs.slice(0, k).every((d) => d < 0) && a.diffs.slice(k).every((d) => d > 0);
});
definePattern('Smooth Chain', 'Neighbouring letters are never more than 3 alphabet places apart', 'jump', (a) => a.diffs.every((d) => Math.abs(d) <= 3));
definePattern('Tight Chain', 'Neighbouring letters are never more than 1 alphabet place apart', 'jump', (a) => a.diffs.every((d) => Math.abs(d) <= 1));
definePattern('Jagged Leaps', 'Neighbouring letters are always at least 9 alphabet places apart', 'jump', (a) => a.diffs.every((d) => Math.abs(d) >= 9));

/* Parity and primes */
definePattern('All Odd Positions', 'Every letter has an odd alphabet position (A, C, E...)', 'parity', (a) => a.allPos((p) => p % 2 === 1));
definePattern('All Even Positions', 'Every letter has an even alphabet position (B, D, F...)', 'parity', (a) => a.allPos((p) => p % 2 === 0));
definePattern('Mostly Odd', 'Exactly six letters have odd alphabet positions', 'parity', (a) => a.pos.filter((p) => p % 2 === 1).length === 6);
definePattern('Mostly Even', 'Exactly six letters have even alphabet positions', 'parity', (a) => a.pos.filter((p) => p % 2 === 0).length === 6);
definePattern('Alternating Parity', 'Odd and even alphabet positions alternate', 'parity', (a) => a.pos.every((p, i) => i === 0 || (p + a.pos[i - 1]) % 2 === 1));
definePattern('Prime Majority', 'At least five letters sit at prime alphabet positions (B C E G K M Q S W)', 'prime', (a) => a.pos.filter((p) => PRIMES.has(p)).length >= 5);
definePattern('Prime Supermajority', 'At least six letters sit at prime alphabet positions', 'prime', (a) => a.pos.filter((p) => PRIMES.has(p)).length >= 6);
definePattern('All Prime', 'Every letter sits at a prime alphabet position', 'prime', (a) => a.allPos((p) => PRIMES.has(p)));
definePattern('Prime Free', 'No letter sits at a prime alphabet position', 'prime', (a) => a.allPos((p) => !PRIMES.has(p)));

/* Number sets (all seven letters must belong) */
definePattern('Fibonacci Letters', 'All positions are Fibonacci numbers (A B C E H M U)', 'numset', (a) => a.allPos((p) => FIBONACCI.has(p)));
definePattern('Square Letters', 'All positions are perfect squares (A D I P Y)', 'numset', (a) => a.allPos((p) => SQUARES.has(p)));
definePattern('Power-of-Two Letters', 'All positions are powers of two (A B D H P)', 'numset', (a) => a.allPos((p) => POWERS_OF_TWO.has(p)));
definePattern('Triangular Letters', 'All positions are triangular numbers (A C F J O U)', 'numset', (a) => a.allPos((p) => TRIANGULAR.has(p)));
definePattern('Multiples of 3', 'All positions are multiples of 3 (C F I L O R U X)', 'numset', (a) => a.allPos((p) => p % 3 === 0));
definePattern('Multiples of 4', 'All positions are multiples of 4 (D H L P T X)', 'numset', (a) => a.allPos((p) => p % 4 === 0));
definePattern('Multiples of 5', 'All positions are multiples of 5 (E J O T Y)', 'numset', (a) => a.allPos((p) => p % 5 === 0));
definePattern('Same Remainder mod 3', 'All positions leave the same remainder when divided by 3', 'numset', (a) => a.allPos((p) => p % 3 === a.pos[0] % 3));
definePattern('Same Remainder mod 4', 'All positions leave the same remainder when divided by 4', 'numset', (a) => a.allPos((p) => p % 4 === a.pos[0] % 4));

/* Alphabet ranges */
definePattern('First Half Only', 'All letters are from A-M', 'range', (a) => a.max <= 13);
definePattern('Second Half Only', 'All letters are from N-Z', 'range', (a) => a.min >= 14);
definePattern('Single-Digit Letters', 'All letters are from A-I (positions 1-9)', 'range', (a) => a.max <= 9);
definePattern('Double-Digit Letters', 'All letters are from J-Z (positions 10-26)', 'range', (a) => a.min >= 10);
definePattern('Opening Seven', 'All letters are from A-G', 'range', (a) => a.max <= 7);
definePattern('Closing Seven', 'All letters are from T-Z', 'range', (a) => a.min >= 20);
definePattern('Middle Band', 'All letters are from H-S', 'range', (a) => a.min >= 8 && a.max <= 19);
definePattern('Narrow Window', 'All letters fit inside a 7-letter stretch of the alphabet', 'tight', (a) => a.max - a.min <= 6);
definePattern('Tiny Window', 'All letters fit inside a 5-letter stretch of the alphabet', 'tight', (a) => a.max - a.min <= 4);
definePattern('Wide Span', 'The smallest and largest letters are at least 24 places apart', 'wide', (a) => a.max - a.min >= 24);
definePattern('Alpha and Omega', 'Both A and Z are present', 'wide', (a) => a.has('A') && a.has('Z'));

/* Alphabet-position sums */
definePattern('Prime Sum', 'The alphabet positions add up to a prime number', 'sum', (a) => { if (a.sum < 2) return false; for (let d = 2; d * d <= a.sum; d++) if (a.sum % d === 0) return false; return true; });
definePattern('Square Sum', 'The alphabet positions add up to a perfect square', 'sum', (a) => Number.isInteger(Math.sqrt(a.sum)));
definePattern('Lucky Sevens Sum', 'The alphabet positions add up to a multiple of 7', 'sum', (a) => a.sum % 7 === 0);
definePattern('Full Cycle Sum', 'The alphabet positions add up to a multiple of 26', 'sum', (a) => a.sum % 26 === 0);
definePattern('Century Sum', 'The alphabet positions add up to exactly 100', 'sum', (a) => a.sum === 100);
definePattern('Triple Seven Sum', 'The alphabet positions add up to exactly 77', 'sum', (a) => a.sum === 77);
definePattern('Palindromic Sum', 'The alphabet-position total reads the same backwards (e.g. 77, 101)', 'sum', (a) => isPalindromeNumber(a.sum));
definePattern('Featherweight', 'The alphabet positions add up to 45 or less', 'sum-extreme', (a) => a.sum <= 45);
definePattern('Heavyweight', 'The alphabet positions add up to 140 or more', 'sum-extreme', (a) => a.sum >= 140);
definePattern('Balanced Halves', 'The first three letters and last three letters have equal alphabet sums', 'sum', (a) => a.pos[0] + a.pos[1] + a.pos[2] === a.pos[4] + a.pos[5] + a.pos[6]);

/* Vowel counts (exactly one of these always matches) */
['No Vowels', 'Lone Vowel', 'Two Vowels', 'Three Vowels', 'Four Vowels', 'Five Vowels', 'Six Vowels', 'Vowels Only'].forEach((name, n) => {
  definePattern(name, 'Exactly ' + n + ' of the seven letters are vowels (A E I O U)' + (n === 0 ? ' - consonants only' : ''), 'vowel-count', (a) => a.vowelCount === n);
});

/* Vowel / consonant structure */
definePattern('Alternating Vowels and Consonants', 'Vowels and consonants alternate (VCVCVCV or CVCVCVC)', 'vc-alt', (a) => a.mask === 'VCVCVCV' || a.mask === 'CVCVCVC');
[4, 5, 6].forEach((k) => definePattern('Consonant Cluster x' + k, k + ' or more consonants in a row', 'consonant-cluster', (a) => a.consonantRuns.some((r) => r >= k)));
[3, 4, 5].forEach((k) => definePattern('Vowel Block x' + k, k + ' or more vowels in a row', 'vowel-block', (a) => a.vowelRuns.some((r) => r >= k)));
definePattern('Vowels Then Consonants', 'Every vowel comes before every consonant', 'vc-order', (a) => /^V+C+$/.test(a.mask));
definePattern('Consonants Then Vowels', 'Every consonant comes before every vowel', 'vc-order', (a) => /^C+V+$/.test(a.mask));
definePattern('Mirrored Vowel Shape', 'The vowel/consonant layout is a palindrome and includes both kinds', 'vc-order', (a) => a.mask === reverseString(a.mask) && a.vowelCount > 0 && a.vowelCount < 7);
definePattern('Vowel Bookends', 'The roll starts and ends with a vowel', 'vc-ends', (a) => a.isVowel[0] && a.isVowel[6]);
definePattern('Consonant Bookends', 'The roll starts and ends with a consonant', 'vc-ends', (a) => !a.isVowel[0] && !a.isVowel[6]);
definePattern('Hard Cluster', 'Three or more consonants in a row including one of J K Q V W X Z', 'hard-cluster', (a) => /C{3,}/.test(a.mask) && (a.str.match(/[^AEIOU]{3,}/g) || []).some((m) => m.split('').some((c) => HARD_CONSONANTS.has(c))));

/* Vowel distributions */
definePattern('Vowel Trio', 'At least three different vowels appear', 'vowel-kinds', (a) => a.vowelKinds.size >= 3);
definePattern('Vowel Quartet', 'At least four different vowels appear', 'vowel-kinds', (a) => a.vowelKinds.size >= 4);
definePattern('All Five Vowels', 'A, E, I, O and U all appear', 'vowel-kinds', (a) => a.vowelKinds.size === 5);
definePattern('Mono-Vowel', 'Three or more vowels, all the same vowel', 'mono-vowel', (a) => a.vowelCount >= 3 && a.vowelKinds.size === 1);
definePattern('Vowel Staircase', 'At least three vowels appear in strictly rising alphabetical order', 'vowel-stairs', (a) => a.vowels.length >= 3 && a.vowels.every((v, i) => i === 0 || v > a.vowels[i - 1]));
definePattern('Reverse Vowel Staircase', 'At least three vowels appear in strictly falling alphabetical order', 'vowel-stairs', (a) => a.vowels.length >= 3 && a.vowels.every((v, i) => i === 0 || v < a.vowels[i - 1]));
definePattern('Double Vowel', 'The same vowel appears twice side by side', 'double-vowel', (a) => /(A{2}|E{2}|I{2}|O{2}|U{2})/.test(a.str));

/* Rare letters */
['Q', 'X', 'Z', 'J', 'K'].forEach((c) => definePattern('Has ' + c, 'The roll contains the rare letter ' + c, 'rare-' + c, (a) => a.has(c)));
definePattern('Rare Pair', 'At least two different letters from Q X Z J K', 'rare-count', (a) => a.rareKinds.size >= 2);
definePattern('Rare Trio', 'At least three different letters from Q X Z J K', 'rare-count', (a) => a.rareKinds.size >= 3);
definePattern('Rare Quartet', 'At least four different letters from Q X Z J K', 'rare-count', (a) => a.rareKinds.size >= 4);
definePattern('Rare Quintet', 'All of Q, X, Z, J and K appear', 'rare-count', (a) => a.rareKinds.size === 5);
definePattern('Rare Repeater', 'A rare letter (Q X Z J K) appears at least twice', 'rare-repeat', (a) => [...RARE_FIVE].some((c) => a.counts[c] >= 2));
definePattern('Queenless Q', 'Q appears with no U to follow it', 'q-u', (a) => a.has('Q') && !a.has('U'));
definePattern('Q Meets U', 'Both Q and U appear', 'q-u', (a) => a.has('Q') && a.has('U'));
definePattern('Q-U Adjacent', 'The letters Q and U appear side by side as QU', 'q-u', (a) => a.str.includes('QU'));

/* Letter-frequency sets */
definePattern('Common Letters Only', 'Every letter is one of E T A O I N S H R D L U', 'freq-set', (a) => a.allIn(TOP_TWELVE));
definePattern('Final Round', 'Every letter is one of R S T L N E', 'freq-set', (a) => a.allIn(WHEEL_SIX));
definePattern('Off the Beaten Path', 'No letter is one of E T A O I N S H R', 'freq-set', (a) => a.letters.every((c) => !TOP_NINE.has(c)));

/* Keyboard and glyph shapes */
definePattern('Top Row', 'Every letter is on the top QWERTY row', 'keyboard', (a) => a.allIn(KEY_TOP));
definePattern('Home Row', 'Every letter is on the home QWERTY row', 'keyboard', (a) => a.allIn(KEY_HOME));
definePattern('Bottom Row', 'Every letter is on the bottom QWERTY row', 'keyboard', (a) => a.allIn(KEY_BOTTOM));
definePattern('Straight Lines Only', 'Every letter is drawn with straight lines only', 'glyph', (a) => a.allIn(STRAIGHT_LETTERS));
definePattern('Curves Only', 'Every letter is one of C G J O S U (no straight strokes)', 'glyph', (a) => a.allIn(CURVED_LETTERS));
definePattern('Symmetric Glyphs', 'Every letter looks the same when mirrored (A H I M O T U V W X Y)', 'glyph', (a) => a.allIn(SYMMETRIC_LETTERS));
definePattern('Enclosed Spaces', 'Every letter has a closed loop (A B D O P Q R)', 'glyph', (a) => a.allIn(ENCLOSED_LETTERS));

/* Words hidden in the roll order (dictionary-based) */
[3, 4, 5, 6, 7].forEach((k) => definePattern('Hidden Word x' + k, 'A real ' + k + '-letter English word appears in reading order', 'in-order', (a) => hasWordInOrder(a.str, k)));
[4, 5, 6, 7].forEach((k) => definePattern('Backwards Word x' + k, 'A real ' + k + '-letter English word appears when reading the roll backwards', 'reverse-word', (a) => hasWordInOrder(reverseString(a.str), k)));
definePattern('Two-Word Split', 'The roll splits into a 3-letter and a 4-letter real word (either order)', 'split', (a) => (isWord(a.str.slice(0, 3)) && isWord(a.str.slice(3))) || (isWord(a.str.slice(0, 4)) && isWord(a.str.slice(4))));
definePattern('Reversible Word', 'The whole roll is a word and its reverse is also a word', 'semordnilap', (a) => isWord(a.str) && isWord(reverseString(a.str)));

/* Palindromes inside the roll */
[3, 4, 5, 6].forEach((k) => definePattern('Inner Palindrome x' + k, 'A palindrome of at least ' + k + ' letters appears side by side', 'sub-palindrome', (a) => {
  for (let n = k; n <= 7; n++) if (hasContiguousPalindrome(a.str, n)) return true;
  return false;
}));

/* Sandwiches and alternators */
definePattern('Sandwich', 'A letter repeats with exactly one letter between (e.g. EXE)', 'sandwich', (a) => a.letters.some((c, i) => i >= 2 && c === a.letters[i - 2]));
definePattern('Double Sandwich', 'Two separate sandwiches (letter, gap, same letter)', 'sandwich', (a) => a.letters.filter((c, i) => i >= 2 && c === a.letters[i - 2]).length >= 2);
definePattern('Alternator', 'Two different letters alternate for four places (ABAB)', 'sandwich', (a) => a.letters.some((c, i) => i >= 3 && c === a.letters[i - 2] && a.letters[i - 1] === a.letters[i - 3] && c !== a.letters[i - 1]));

/* Bookends */
definePattern('Bookends', 'The first and last letters are identical', 'ends', (a) => a.letters[0] === a.letters[6]);
definePattern('Neighbour Bookends', 'The first and last letters are next to each other in the alphabet', 'ends', (a) => Math.abs(a.pos[0] - a.pos[6]) === 1);
definePattern('Alpha-Omega Bookends', 'The roll starts with A and ends with Z, or the reverse', 'ends', (a) => (a.pos[0] === 1 && a.pos[6] === 26) || (a.pos[0] === 26 && a.pos[6] === 1));

/* Fixed points: letter n of the roll is the n-th letter of the alphabet */
[1, 2, 3, 4, 7].forEach((k) => definePattern('Fixed Points x' + k, k === 7 ? 'The roll is exactly ABCDEFG' : 'At least ' + k + ' letters sit at their own alphabet position (1st = A, 2nd = B...)', 'fixed', (a) => a.fixedPoints >= k));

/* Alphabet starters and finishers */
definePattern('Alphabet Starter', 'A, B and C all appear', 'alphabet-start', (a) => a.has('A') && a.has('B') && a.has('C'));
definePattern('Alphabet Finisher', 'X, Y and Z all appear', 'alphabet-end', (a) => a.has('X') && a.has('Y') && a.has('Z'));

// Attach calibrated tier and points.
const DEFAULT_PATTERN_POINTS = 10;
PATTERN_DEFS.forEach((d) => {
  const t = PATTERN_TABLE[d.id];
  d.tier = t ? t.tier : 'Common';
  d.points = t ? t.points : DEFAULT_PATTERN_POINTS;
  d.probability = t ? t.p : null;
});

/* ------------------------- 2. WORD DETECTION ---------------------------- */
// Enumerates every sub-multiset of the 7 letters (127 subsets) and looks it up by sorted-letter
// signature, so a letter is never used more often than it was rolled.
function findEnglishWords(letters) {
  const seen = new Set();
  const found = [];
  const n = letters.length;
  for (let mask = 1; mask < (1 << n); mask++) {
    const chosen = [];
    for (let i = 0; i < n; i++) if (mask & (1 << i)) chosen.push(letters[i]);
    if (chosen.length < MIN_WORD) continue;
    const sig = chosen.sort().join('');
    if (seen.has(sig)) continue;
    seen.add(sig);
    const list = BY_SIGNATURE.get(sig);
    if (!list) continue;
    for (const word of list) {
      const info = WORDS.get(word);
      found.push({ word, length: word.length, rank: info.rank, definition: info.definition, usesAllSeven: word.length === n });
    }
  }
  return found;
}

/* ----------------------- 3. WORD RARITY AND BONUS ------------------------ */
function wordTierIndex(rank) {
  if (!rank) return WORD_TIERS.length - 1;   // not in the frequency list at all: Mythical
  for (let i = 0; i < WORD_RANK_BOUNDS.length; i++) if (rank <= WORD_RANK_BOUNDS[i]) return i;
  return WORD_TIERS.length - 1;
}
function calculateWordRarity(entry) {
  const tierIndex = wordTierIndex(entry.rank);
  let bonus = WORD_LENGTH_BASE[entry.length] * WORD_TIER_MULTIPLIER[tierIndex];
  if (entry.usesAllSeven) bonus = bonus * ALL_SEVEN_MULTIPLIER + ALL_SEVEN_FLAT;
  return { tier: WORD_TIERS[tierIndex], tierIndex, bonus: Math.round(bonus) };
}
function sortWords(words) {
  return words.slice().sort((x, y) => y.tierIndex - x.tierIndex || y.length - x.length || y.bonus - x.bonus || (x.word < y.word ? -1 : 1));
}

/* ------------------------------ PATTERNS --------------------------------- */
function detectPatterns(profile) {
  return PATTERN_DEFS.filter((d) => d.test(profile)).map((d) => ({
    id: d.id, name: d.name, description: d.description, group: d.group, tier: d.tier, points: d.points, probability: d.probability,
  }));
}
// Overlap rule: within one overlap group only the highest-value pattern counts; the surviving
// group winners are then ranked and weighted PATTERN_DECAY^i so stacking has diminishing returns.
function calculatePatternRarity(patterns) {
  const winners = new Map();
  for (const p of patterns) {
    const cur = winners.get(p.group);
    if (!cur || p.points > cur.points) winners.set(p.group, p);
  }
  const ranked = [...winners.values()].sort((x, y) => y.points - x.points || (x.id < y.id ? -1 : 1));
  const counted = new Map();
  let total = 0;
  ranked.forEach((p, i) => {
    const value = p.points * Math.pow(PATTERN_DECAY, i);
    counted.set(p.id, value);
    total += value;
  });
  const detail = patterns.map((p) => Object.assign({}, p, { counted: Math.round(counted.get(p.id) || 0), isCounted: counted.has(p.id) }));
  return { total: Math.round(total), detail };
}

/* ------------------------------- SCORING --------------------------------- */
function calculateLetterRarity(letters) {
  const seen = {};
  let total = 0;
  const detail = letters.map((c) => {
    const base = Math.round(LETTER_POINT_FACTOR * -Math.log2(LETTER_FREQUENCY[c]));
    const points = seen[c] ? Math.round(base * REPEAT_LETTER_WEIGHT) : base;
    seen[c] = true;
    total += points;
    return { letter: c, points };
  });
  return { total, detail };
}
function calculateWordPoints(words) {
  const bonuses = words.map((w) => w.bonus).sort((x, y) => y - x);
  return Math.round(bonuses.reduce((s, b, i) => s + b * Math.pow(WORD_DECAY, i), 0));
}
// LEP = letter rarity points + pattern points (overlap-resolved) + word bonus points (decayed).
function calculateLEP(letters, patterns, words) {
  const letterRarity = calculateLetterRarity(letters);
  const patternRarity = calculatePatternRarity(patterns);
  const wordPoints = calculateWordPoints(words);
  return {
    letterPoints: letterRarity.total,
    patternPoints: patternRarity.total,
    wordPoints,
    total: letterRarity.total + patternRarity.total + wordPoints,
    patternDetail: patternRarity.detail,
    letterDetail: letterRarity.detail,
  };
}

/* ------------------------- PROBABILITY AND TIER -------------------------- */
// P(a random roll scores >= lep), interpolated in log space from the simulated distribution.
function estimateProbability(lep) {
  const t = LEP_TABLE;
  if (!t.length) return null;
  if (lep <= t[0][0]) return 1;
  for (let i = 1; i < t.length; i++) {
    if (lep <= t[i][0]) {
      const [x0, p0] = t[i - 1], [x1, p1] = t[i];
      const f = (lep - x0) / (x1 - x0);
      return Math.exp(Math.log(p0) + f * (Math.log(p1) - Math.log(p0)));
    }
  }
  // Beyond the simulated range: continue the slope of the last segment (an estimate).
  const [x0, p0] = t[t.length - 2], [x1, p1] = t[t.length - 1];
  const slope = (Math.log(p1) - Math.log(p0)) / (x1 - x0);
  return Math.exp(Math.log(p1) + slope * (lep - x1));
}
function determineRarityTier(lep) {
  const p = estimateProbability(lep);
  if (p === null) return OVERALL_TIERS[0];
  let index = 0;
  for (const cutoff of TIER_PROBABILITY_CUTOFFS) if (p <= cutoff) index++;
  return OVERALL_TIERS[index];
}

/* ------------------------------ ANALYSIS --------------------------------- */
function analyzeLetters(letters) {
  const profile = buildProfile(letters);
  const patterns = detectPatterns(profile);
  const words = sortWords(findEnglishWords(letters).map((w) => Object.assign(w, calculateWordRarity(w))));
  const lep = calculateLEP(letters, patterns, words);
  const probability = estimateProbability(lep.total);
  return {
    letters: letters.slice(),
    str: letters.join(''),
    letterDetail: lep.letterDetail,
    patterns: sortPatterns(lep.patternDetail),
    words,
    letterPoints: lep.letterPoints,
    patternPoints: lep.patternPoints,
    wordPoints: lep.wordPoints,
    lep: lep.total,
    tier: determineRarityTier(lep.total),
    probability,
  };
}
function sortPatterns(list) {
  return list.slice().sort((x, y) => OVERALL_TIERS.indexOf(y.tier) - OVERALL_TIERS.indexOf(x.tier) || y.points - x.points || (x.id < y.id ? -1 : 1));
}

/* ------------------------- STORAGE, HISTORY, STATS ----------------------- */
const memoryStore = {};
function storageGet(key) {
  try { const v = localStorage.getItem(key); if (v !== null) return v; } catch (e) { /* unavailable */ }
  return key in memoryStore ? memoryStore[key] : null;
}
function storageSet(key, value) {
  memoryStore[key] = value;
  try { localStorage.setItem(key, value); return true; } catch (e) { return false; }
}
function emptyStats() {
  return {
    totalRolls: 0, highestLep: 0, highestLepLetters: '',
    rarest: null, longestWord: null, totalWords: 0, uniqueWords: [],
    tierCounts: OVERALL_TIERS.reduce((o, t) => { o[t] = 0; return o; }, {}),
  };
}
function loadHistory() {
  try { const h = JSON.parse(storageGet(STORAGE_KEYS.history) || '[]'); return Array.isArray(h) ? h : []; } catch (e) { return []; }
}
function loadStats() {
  try {
    const s = JSON.parse(storageGet(STORAGE_KEYS.stats) || 'null');
    return s ? Object.assign(emptyStats(), s) : emptyStats();
  } catch (e) { return emptyStats(); }
}
function saveHistory(result) {
  const history = loadHistory();
  const best = result.words[0];
  history.unshift({
    n: loadStats().totalRolls, time: Date.now(), letters: result.str, lep: result.lep, tier: result.tier,
    probability: result.probability, words: result.words.length, patterns: result.patterns.length,
    bestWord: best ? best.word : '',
  });
  history.length = Math.min(history.length, HISTORY_LIMIT);
  storageSet(STORAGE_KEYS.history, JSON.stringify(history));
  return history;
}
function updateStatistics(result) {
  const s = loadStats();
  s.totalRolls += 1;
  if (result.lep > s.highestLep) { s.highestLep = result.lep; s.highestLepLetters = result.str; }
  if (!s.rarest || (result.probability !== null && result.probability < s.rarest.probability)) {
    s.rarest = { letters: result.str, tier: result.tier, probability: result.probability, lep: result.lep };
  }
  for (const w of result.words) {
    if (!s.longestWord || w.length > s.longestWord.length || (w.length === s.longestWord.length && w.tierIndex > s.longestWord.tierIndex)) {
      s.longestWord = { word: w.word, length: w.length, tier: w.tier, tierIndex: w.tierIndex };
    }
  }
  s.totalWords += result.words.length;
  const unique = new Set(s.uniqueWords);
  result.words.forEach((w) => unique.add(w.word));
  s.uniqueWords = [...unique];
  s.tierCounts[result.tier] = (s.tierCounts[result.tier] || 0) + 1;
  storageSet(STORAGE_KEYS.stats, JSON.stringify(s));
  return s;
}
function clearSavedData() {
  storageSet(STORAGE_KEYS.history, '[]');
  storageSet(STORAGE_KEYS.stats, JSON.stringify(emptyStats()));
}

/* ------------------------------- DISPLAY --------------------------------- */
const REDUCED_MOTION = typeof matchMedia !== 'undefined' && matchMedia('(prefers-reduced-motion: reduce)').matches;
const NOTABLE_PATTERN_TIERS = ['Epic', 'Legendary', 'Mythical', 'Divine', 'Secret'];
const RARE_LETTER_POINTS = 28;   // letters worth at least this many points get a gold tile

function formatOdds(p) {
  if (p === null || p === undefined) return 'n/a';
  if (p >= 0.995) return 'almost every roll';
  const n = 1 / p;
  const approx = n >= 100000 ? '~' : '';
  return approx + '1 in ' + (n < 10 ? n.toFixed(1) : Math.round(n).toLocaleString('en-US')) + ' (' + (p >= 0.01 ? (p * 100).toFixed(1) : (p * 100).toPrecision(2)) + '%)';
}
function el(tag, text, attrs) {
  const node = document.createElement(tag);
  if (text !== undefined && text !== null) node.textContent = String(text);
  if (attrs) Object.keys(attrs).forEach((k) => node.setAttribute(k, attrs[k]));
  return node;
}
function chip(tier, size) {
  const c = el('span', tier, { 'data-tier': tier });
  c.className = 'chip' + (size ? ' chip-' + size : '');
  return c;
}
function fillTable(tbody, rows) {
  tbody.textContent = '';
  rows.forEach((cells) => {
    const tr = document.createElement('tr');
    cells.forEach((c) => {
      const td = document.createElement('td');
      if (c instanceof Node) td.appendChild(c); else td.textContent = String(c);
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
  });
}
function byId(id) { return document.getElementById(id); }
function sleep(ms) { return new Promise((resolve) => setTimeout(resolve, ms)); }

// Count a number up with an ease-out curve.
function animateNumber(node, to, duration) {
  if (REDUCED_MOTION || to === 0) { node.textContent = to.toLocaleString('en-US'); return; }
  const start = performance.now();
  function frame(now) {
    const t = Math.min(1, (now - start) / duration);
    const eased = 1 - Math.pow(1 - t, 3);
    node.textContent = Math.round(to * eased).toLocaleString('en-US');
    if (t < 1) requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

/* ---- letter tiles ---- */
function createTiles() {
  const list = byId('letters');
  list.textContent = '';
  for (let i = 0; i < ROLL_LENGTH; i++) {
    const tile = el('li');
    tile.className = 'tile';
    tile.appendChild(el('span', '?', { 'class': 'tile-face' }));
    tile.appendChild(el('small', '', { 'class': 'tile-points' }));
    list.appendChild(tile);
  }
}
function setTile(tile, letter, points) {
  tile.querySelector('.tile-face').textContent = letter;
  tile.querySelector('.tile-points').textContent = points !== undefined ? '+' + points : '';
  if (points >= RARE_LETTER_POINTS) tile.setAttribute('data-rare', 'true'); else tile.removeAttribute('data-rare');
}
// Slot-machine roll: every tile cycles random letters, then locks left to right.
function animateLetters(letters, detail) {
  const tiles = Array.from(byId('letters').children);
  tiles.forEach((tile) => {
    tile.classList.remove('locked');
    tile.classList.add('spinning');
    tile.removeAttribute('data-rare');
    tile.querySelector('.tile-points').textContent = '';
  });
  return new Promise((resolve) => {
    const spinner = setInterval(() => {
      tiles.forEach((tile) => {
        if (tile.classList.contains('spinning')) tile.querySelector('.tile-face').textContent = ALPHABET[randomInt(26)];
      });
    }, 65);
    tiles.forEach((tile, i) => {
      setTimeout(() => {
        tile.classList.remove('spinning');
        setTile(tile, letters[i], detail[i].points);
        void tile.offsetWidth; // restart the lock animation
        tile.classList.add('locked');
        if (i === tiles.length - 1) { clearInterval(spinner); setTimeout(resolve, REDUCED_MOTION ? 0 : 450); }
      }, REDUCED_MOTION ? 0 : 750 + i * 260);
    });
  });
}

/* ---- results ---- */
function patternCard(p, index) {
  const li = el('li');
  li.className = 'pattern-card' + (NOTABLE_PATTERN_TIERS.includes(p.tier) ? ' is-notable' : '') + (p.isCounted ? '' : ' is-overlap');
  li.setAttribute('data-tier', p.tier);
  li.style.setProperty('--delay', Math.min(index * 80, 1800) + 'ms');
  const top = el('div'); top.className = 'pattern-top';
  top.appendChild(chip(p.tier));
  top.appendChild(el('span', p.points + ' pts', { 'class': 'pattern-points' }));
  li.appendChild(top);
  li.appendChild(el('h4', p.name, { 'class': 'pattern-name' }));
  li.appendChild(el('p', p.description, { 'class': 'pattern-desc' }));
  const foot = el('div'); foot.className = 'pattern-foot';
  foot.appendChild(el('span', p.id, { 'class': 'pattern-id' }));
  foot.appendChild(el('span', p.isCounted ? '+' + p.counted + ' LEP' : 'overlap, not counted', { 'class': 'pattern-counted' }));
  li.appendChild(foot);
  return li;
}
function wordRow(w, index) {
  const tr = document.createElement('tr');
  tr.className = 'word-row' + (w.usesAllSeven ? ' is-full' : '');
  tr.style.setProperty('--delay', Math.min(index * 35, 1400) + 'ms');
  const cells = [
    el('strong', w.word, { 'class': 'word-text' }), w.length, chip(w.tier), '+' + w.bonus,
    w.usesAllSeven ? el('span', '7 / 7', { 'class': 'badge-all' }) : '-',
    el('span', w.definition || '(no definition available)', { 'class': w.definition ? '' : 'muted' }),
  ];
  cells.forEach((c) => {
    const td = document.createElement('td');
    if (c instanceof Node) td.appendChild(c); else td.textContent = String(c);
    tr.appendChild(td);
  });
  return tr;
}

function displayResults(result) {
  const results = byId('results');
  results.hidden = false;
  results.classList.remove('is-visible');

  const tiles = Array.from(byId('letters').children);
  result.letters.forEach((c, i) => setTile(tiles[i], c, result.letterDetail[i].points));

  byId('stage').setAttribute('data-tier', result.tier);
  results.setAttribute('data-tier', result.tier);
  animateNumber(byId('out-lep'), result.lep, 1100);
  const tierNode = byId('out-tier');
  tierNode.textContent = result.tier;
  tierNode.setAttribute('data-tier', result.tier);
  byId('out-letter-points').textContent = result.letterPoints.toLocaleString('en-US');
  byId('out-pattern-points').textContent = result.patternPoints.toLocaleString('en-US');
  byId('out-word-points').textContent = result.wordPoints.toLocaleString('en-US');
  byId('out-probability').textContent = formatOdds(result.probability);
  const total = Math.max(1, result.letterPoints + result.patternPoints + result.wordPoints);
  byId('seg-letters').style.setProperty('--w', (result.letterPoints / total * 100).toFixed(2));
  byId('seg-patterns').style.setProperty('--w', (result.patternPoints / total * 100).toFixed(2));
  byId('seg-words').style.setProperty('--w', (result.wordPoints / total * 100).toFixed(2));

  const counted = result.patterns.filter((p) => p.isCounted).length;
  byId('pattern-count').textContent = result.patterns.length + ' detected, ' + counted + ' counted toward LEP';
  const list = byId('pattern-list');
  list.textContent = '';
  result.patterns.forEach((p, i) => list.appendChild(patternCard(p, i)));

  const words = result.words;
  byId('word-count').textContent = words.length + ' valid English word' + (words.length === 1 ? '' : 's') + ' found (' + words.filter((w) => w.usesAllSeven).length + ' using all 7 letters)';
  const body = byId('word-rows');
  body.textContent = '';
  words.forEach((w, i) => body.appendChild(wordRow(w, i)));

  void results.offsetWidth; // restart CSS transitions and animations
  results.classList.add('is-visible');
}

function renderStatistics(stats) {
  byId('stat-rolls').textContent = stats.totalRolls.toLocaleString('en-US');
  byId('stat-highest').textContent = stats.totalRolls ? stats.highestLep.toLocaleString('en-US') + ' (' + stats.highestLepLetters + ')' : '-';
  byId('stat-rarest').textContent = stats.rarest ? stats.rarest.letters + ' - ' + stats.rarest.tier + ', ' + formatOdds(stats.rarest.probability) : '-';
  byId('stat-longest').textContent = stats.longestWord ? stats.longestWord.word + ' (' + stats.longestWord.length + ' letters, ' + stats.longestWord.tier + ')' : '-';
  byId('stat-words').textContent = stats.totalWords.toLocaleString('en-US');
  byId('stat-unique').textContent = stats.uniqueWords.length.toLocaleString('en-US');
  ['Legendary', 'Mythical', 'Divine', 'Secret'].forEach((t) => { byId('stat-' + t.toLowerCase()).textContent = stats.tierCounts[t] || 0; });
  fillTable(byId('tier-rows'), OVERALL_TIERS.map((t) => [chip(t), stats.tierCounts[t] || 0]));
}
function renderHistory(history) {
  const shown = history.slice(0, HISTORY_DISPLAY);
  byId('history-empty').hidden = shown.length > 0;
  byId('history-table').hidden = shown.length === 0;
  fillTable(byId('history-rows'), shown.map((h) => [
    h.n + 1, new Date(h.time).toLocaleString(), el('strong', h.letters, { 'class': 'word-text' }), h.lep.toLocaleString('en-US'),
    chip(h.tier), formatOdds(h.probability), h.words, h.bestWord || '-', h.patterns,
  ]));
}

/* --------------------------------- UI ------------------------------------ */
let rolling = false;
async function rollOnce() {
  if (rolling) return;
  rolling = true;
  const button = byId('roll-button');
  button.disabled = true;
  button.textContent = 'ROLLING';
  byId('stage').removeAttribute('data-tier');
  byId('stage').classList.add('is-rolling');
  byId('results').classList.remove('is-visible');
  byId('status').textContent = 'Rolling...';

  const letters = generateLetters();
  const result = analyzeLetters(letters);
  await animateLetters(result.letters, result.letterDetail);

  // saveHistory numbers the entry from the roll count before this roll, so it must run first.
  const history = saveHistory(result);
  const stats = updateStatistics(result);
  byId('stage').classList.remove('is-rolling');
  displayResults(result);
  renderStatistics(stats);
  renderHistory(history);
  byId('status').textContent = 'Rolled ' + result.str + ': ' + result.lep.toLocaleString('en-US') + ' LEP (' + result.tier + ').';
  button.disabled = false;
  button.textContent = 'ROLL AGAIN';
  rolling = false;
}
function initUI() {
  createTiles();
  byId('roll-button').addEventListener('click', rollOnce);
  byId('clear-button').addEventListener('click', () => {
    if (window.confirm('Delete all saved history and statistics?')) {
      clearSavedData();
      renderStatistics(loadStats());
      renderHistory(loadHistory());
      byId('status').textContent = 'History and statistics cleared.';
    }
  });
  byId('dictionary-info').textContent = WORDS.size.toLocaleString('en-US') + ' words';
  byId('pattern-total').textContent = PATTERN_DEFS.length;
  fillTable(byId('catalog-rows'), PATTERN_DEFS.map((d) => [d.id, d.name, d.description, chip(d.tier), d.points]));
  renderStatistics(loadStats());
  renderHistory(loadHistory());
}
const manualInput = document.getElementById('manual-letters');
const manualScoreButton = document.getElementById('manual-score-button');
const manualStatus = document.getElementById('manual-status');
const manualResult = document.getElementById('manual-result');
const manualLep = document.getElementById('manual-lep');
const manualTier = document.getElementById('manual-tier');

function normalizeManualLetters(value) {
  return value.replace(/[^a-z]/gi, '').slice(0, 7).toUpperCase();
}

function validateManualLetters(value) {
  const trimmed = value.trim();

  if (!trimmed) {
    return { valid: false, message: 'Please enter exactly 7 English letters.' };
  }

  if (!/^[A-Za-z]+$/.test(trimmed)) {
    return { valid: false, message: 'Please enter only English letters.' };
  }

  if (trimmed.length !== 7) {
    return { valid: false, message: 'Please enter exactly 7 English letters.' };
  }

  return { valid: true, letters: trimmed.toUpperCase() };
}

manualInput.addEventListener('input', () => {
  manualInput.value = normalizeManualLetters(manualInput.value);
});

manualInput.addEventListener('keydown', (event) => {
  if (event.key === 'Enter') {
    event.preventDefault();
    manualScoreButton.click();
  }
});

manualScoreButton.addEventListener('click', () => {
  const validation = validateManualLetters(manualInput.value);

  if (!validation.valid) {
    manualResult.hidden = true;
    manualStatus.textContent = validation.message;
    manualInput.focus();
    return;
  }

  const letters = validation.letters;

  // Replace this with your existing score function if the function name is different.
  // Example:
  // const result = evaluateRoll(letters);
  // const result = scoreLetters(letters);
  // const result = computeRoll(letters);

  const result = evaluateRoll(letters); // <- use your existing game calculator here

  manualLep.textContent = String(result.lep ?? 0);
  manualTier.textContent = result.tier ?? 'Common';
  manualTier.dataset.tier = result.tier ?? 'Common';

  manualResult.hidden = false;
  manualStatus.textContent = `Score for "${letters}" is ready.`;
});

